import{_ as t,C as l,o as n,c as o,j as i,E as r,a as d,a3 as e}from"./chunks/framework.C6R8kWFE.js";const v=JSON.parse(`{"title":"4-hafta","description":"","frontmatter":{"title":"4-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/9-sinf-iot/"},"n":4,"bob":"II-bob · Elektronika va Arduino bilan interaktiv interfeyslar","lessons":[{"g":10,"title":"10-dars: Arduino UNO va tugma orqali LED holatini boshqarish dasturi","lead":"Fonarni bir bosishda yoqasiz, ikkinchi bosishda u miltillay boshlaydi, uchinchisida tez miltillaydi. Bitta tugma — bir nechta rejim. Bugun shunday «aqlli» boshqaruv dasturini yozamiz.","link":"/9-sinf-iot/hafta-04/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-04/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-04/dars-1-test.html"},{"g":11,"title":"11-dars: Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (1-qism)","lead":"Uydagi chiroq kalitini bosganingizda nima sodir bo'ladi? Siz shunchaki elektr zanjirini yopasiz yoki ochasiz. Bugun dasturisiz, faqat breadboard, DIP switch va LED bilan shunday zanjirni o'zimiz yig'amiz.","link":"/9-sinf-iot/hafta-04/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-04/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-04/dars-2-test.html"},{"g":12,"title":"12-dars: Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (2-qism)","lead":"Sanoat pressi ishchi ikkala qo'li bilan ikki tugmani bosgandagina ishlaydi, avtobusdagi «to'xtash» chirog'i esa istalgan tugmadan yonadi. Bu «VA» va «YOKI» mantig'i — bugun uni ikki kalit bilan yig'amiz va DIP switch'ni Arduino'ga ulaymiz.","link":"/9-sinf-iot/hafta-04/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-04/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-04/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"9-sinf-iot/hafta-04/index.md","filePath":"9-sinf-iot/hafta-04/index.md"}`),h={name:"9-sinf-iot/hafta-04/index.md"},m={class:"blk"},u={id:"uyga-vazifa",tabindex:"-1"};function k(c,a,g,b,y,f){const s=l("Icon");return n(),o("div",null,[i("div",m,[i("h2",u,[r(s,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=e('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan. Natijani Tinkercad havolasi yoki skrinshotlar bilan topshiring.</p><hr><h3 id="_10-dars-arduino-uno-va-tugma-orqali-led-holatini-boshqarish-dasturi" tabindex="-1">10-dars: Arduino UNO va tugma orqali LED holatini boshqarish dasturi <a class="header-anchor" href="#_10-dars-arduino-uno-va-tugma-orqali-led-holatini-boshqarish-dasturi" aria-label="Permalink to &quot;10-dars: Arduino UNO va tugma orqali LED holatini boshqarish dasturi&quot;">​</a></h3><ol><li>Tinkercad&#39;da Arduino UNO, tugma (Pin 2 → GND) va LED (Pin 9 → 220 Om → GND) sxemasini yig&#39;ing.</li><li><code>delay()</code> ishlatmasdan, <code>millis()</code> asosida 4 rejimli chiroq dasturini yozing: O&#39;CHIQ → YONIQ → SEKIN (500 ms) → TEZ (100 ms) → O&#39;CHIQ.</li><li>Rejim o&#39;zgarganda Serial Monitor&#39;ga <code>Rejim: SEKIN</code> kabi yozuv chiqsin (faqat o&#39;zgarganda).</li><li>Qo&#39;shimcha: Pin 13 ga heartbeat LED qo&#39;shing (700 ms) va u rejimlardan qat&#39;i nazar bir tekis miltillashini ko&#39;rsating.</li></ol><hr><h3 id="_11-dars-dip-switch-dpst-va-led-—-oddiy-elektron-sikl-1-qism" tabindex="-1">11-dars: DIP switch (DPST) va LED — oddiy elektron sikl (1-qism) <a class="header-anchor" href="#_11-dars-dip-switch-dpst-va-led-—-oddiy-elektron-sikl-1-qism" aria-label="Permalink to &quot;11-dars: DIP switch (DPST) va LED — oddiy elektron sikl (1-qism)&quot;">​</a></h3><ol><li>Tinkercad&#39;da 5 V manba, Breadboard, DIP Switch DPST, qizil va yashil LED dan zanjir yig&#39;ing: 1-kontakt Qizil LEDni, 2-kontakt Yashil LEDni mustaqil boshqarsin.</li><li>Har bir LED uchun rezistorni Om qonuni bo&#39;yicha hisoblang (qizil 2 V, yashil 3 V, tok 10 mA) va standart qiymatni tanlang.</li><li>4 ta holat (OFF/OFF, ON/OFF, OFF/ON, ON/ON) jadvalini tuzing va har biriga skrinshot qo&#39;shing.</li><li>Agar manba 9 V bo&#39;lsa, rezistorlar qanday o&#39;zgarishi kerakligini hisob bilan yozing.</li></ol><hr><h3 id="_12-dars-dip-switch-dpst-va-led-—-oddiy-elektron-sikl-2-qism" tabindex="-1">12-dars: DIP switch (DPST) va LED — oddiy elektron sikl (2-qism) <a class="header-anchor" href="#_12-dars-dip-switch-dpst-va-led-—-oddiy-elektron-sikl-2-qism" aria-label="Permalink to &quot;12-dars: DIP switch (DPST) va LED — oddiy elektron sikl (2-qism)&quot;">​</a></h3><ol><li>AND (ketma-ket) va OR (parallel) zanjirlarini yig&#39;ing; har biri uchun haqiqat jadvalini skrinshotlar bilan tasdiqlang.</li><li>Multimetr bilan 220, 330 va 1000 Om rezistorlarda tokni o&#39;lchab, jadval va xulosa yozing.</li><li>DIP switch&#39;ni Arduino&#39;ga ulang (DIP1 → Pin 2, DIP2 → Pin 3, qarama-qarshi oyoqlar GND) va 2 bitli kod bo&#39;yicha 4 rejimli tanlagichni dasturlang: 0 — o&#39;chiq, 1 — Yashil, 2 — Qizil, 3 — navbat bilan miltillash.</li></ol><hr>',11))])])}const D=t(h,[["render",k]]);export{v as __pageData,D as default};
